// THE INVESTIGATION DAMPER STAMPS S, AND AN ALL-REFUSED DECOMPOSITION IS STAMPED LIKE needs_information.
//
// The damper stamped classification_metadata.investigation_declined only for a needs_information decline, with the
// escalation's chronicEscalationFingerprint. A decline where the decomposer drafted steps and the arming refused every
// one ("no valid step: step 1: ...") wrote no stamp, so the gap-goal supply re-sent the same "investigate and decompose"
// walk for the unchanged row on every pick, and each re-draft was refused for a different reason. And that fingerprint
// read the newest failure lesson, which a refused run writes itself, so even a stamp would not have held. The stamp now
// fires on needs_information, "no valid step" or "decomposition_refused" with nothing written. It keeps fingerprint
// byte for byte (the supply's current predicate parses it) and adds row_state = S (rowStateFingerprint), the row-input
// fingerprint shared with the supply: S leaves out everything the investigation writes (its refusal lesson,
// decomposed_at, decomposition, investigated_at, the stamp itself, every *_at key).
//   - [MUST-FAIL] written [] and every step refused, driven through resolveGapToFeature's decompose_gap_id branch on the
//     judge-split harness: investigation_declined.row_state is the row's S, and the stored row's S equals it;
//   - CONTROL: two refused runs with DIFFERENT refusal texts on an unchanged row stamp the SAME S;
//   - CONTROL: the stamp carries fingerprint (byte-identical to the escalation's, as before) and row_state;
//   - CONTROL: a decomposition that wrote a step is not stamped; a needs_information decline is stamped with S; observe
//     mode writes nothing; a row's own stamp does not change its S;
//   - PARITY: every shared S vector (the supply's canonical set, copied inline here) is reproduced byte for byte,
//     canonical string and hash, with its same_as / differs_from relations; fixtures (a) to (f) by name ((f): a
//     detector re-emission that changes only the summary's rolling counts, occurrence_count and example_trace_ids).
import { afterAll, afterEach, beforeEach, describe, expect, it } from "bun:test";
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { beginPin, endPin, restoreHarness, seed, stored, metaOf, writesFor, route, RUN, SCRATCH, type Row } from "./harness.js";

const g2f = await import("../../src/resolvers/gap-to-feature.js");
const VESSEL = "fixture-vessel";
const SITE = `repos/${VESSEL}/src/widget.ts`;
const WIDGET = "export function validateFrame(f: number): boolean {\n  return f > 0;\n}\nexport function countRejected(fs: number[]): number { return fs.filter((f) => !validateFrame(f)).length; }\n";
const decompose = (id: string, extra: Row = {}) => g2f.resolveGapToFeature({ type: "gap_to_feature", decompose_gap_id: id, ...extra } as never);
const S = (row: unknown) => g2f.rowStateFingerprint(row);
const lessonsOf = (id: string) => (metaOf(id).failure_lessons ?? []) as Row[];

/** A step the arming refuses because its file does not exist (the refusal names the file, so two names differ). */
const missingStep = (file: string) => ({ edit_site: `repos/${VESSEL}/src/${file}`, change: "validateFrame must reject zero frames and countRejected must use it", falsifier: { expected_literal: "FRAME_FLOOR_MIN", reader: "validateFrame" } });
/** A step the arming accepts: a literal absent today, read by an existing function in the edit site. */
const validStep = { edit_site: SITE, change: "validateFrame must compare against FRAME_FLOOR_MIN and countRejected must use it", falsifier: { expected_literal: "FRAME_FLOOR_MIN", reader: "validateFrame" } };
const replies: Array<Record<string, unknown>> = [];
function llmRoutes(): void {
  route({ name: "shape descriptions", match: (u) => u.includes("/registry/shape-descriptions"), respond: () => Response.json({ shape_descriptions: {} }) });
  route({ name: "llm", match: (u) => u.startsWith("http://llm.judge-pin"), respond: () => Response.json({ content: JSON.stringify(replies.length > 1 ? replies.shift() : replies[0]) }) });
}
const sitedRow = (suffix: string, meta: Row = {}): Row => seed({ id: `inv-refused-${suffix}-${RUN}`, summary: "The widget frame validator counts rejected frames wrong", classification_metadata: { edit_site: SITE, falsifier: "none", ...meta } });

beforeEach(() => {
  beginPin();
  for (const base of ["clones", "runtime"]) {
    mkdirSync(join(SCRATCH, base, VESSEL, "src"), { recursive: true });
    mkdirSync(join(SCRATCH, base, VESSEL, "test"), { recursive: true });
  }
  writeFileSync(join(SCRATCH, "clones", VESSEL, "src", "widget.ts"), WIDGET);
  writeFileSync(join(SCRATCH, "clones", VESSEL, "test", "widget.test.ts"), 'import { it } from "bun:test";\nit("widget counts rejected frames", () => {});\n');
  replies.length = 0;
  llmRoutes();
});
afterEach(() => { expect(endPin([/pick-decisions\.jsonl$/]).fetch).toEqual([]); });
afterAll(() => restoreHarness());

describe("gapDecomposition's declines stamp S, the row-input fingerprint", () => {
  it("[MUST-FAIL] written [] and every step refused: investigation_declined carries the row's S", async () => {
    const g = sitedRow("mf");
    replies.push({ steps: [missingStep("missing-a.ts")] });
    const r = await decompose(g.id);
    const body = r.body as Row;
    expect(body.children).toEqual([]);
    expect(String(body.reason)).toStartWith("no valid step: step 1: ");
    const stamp = metaOf(g.id).investigation_declined as Row | undefined;
    expect(stamp).toBeDefined();
    expect(stamp!.row_state).toBe(S(g));
    expect(String(stamp!.reason)).toStartWith("no valid step: ");
    // The refusal lesson the run wrote survives the stamp, and the stored row's own S is the stamp's row_state.
    expect(lessonsOf(g.id).map((l) => l.class)).toEqual(["decomposition_refusal"]);
    expect(S(stored(g.id)!)).toBe(String(stamp!.row_state));
    expect(metaOf(g.id).disposition).toBeUndefined();
  });

  it("[CONTROL] two refused runs with DIFFERENT refusal texts on an unchanged row stamp the same S", async () => {
    const g = sitedRow("twice");
    replies.push({ steps: [missingStep("missing-a.ts")] }, { steps: [missingStep("missing-b.ts")] });
    const r1 = await decompose(g.id);
    const s1 = metaOf(g.id).investigation_declined as Row;
    const r2 = await decompose(g.id);
    const s2 = metaOf(g.id).investigation_declined as Row;
    expect(String((r1.body as Row).reason)).toContain("missing-a.ts");
    expect(String((r2.body as Row).reason)).toContain("missing-b.ts");
    expect(lessonsOf(g.id).map((l) => String(l.reason))).toEqual([expect.stringContaining("missing-a.ts"), expect.stringContaining("missing-b.ts")]);
    expect(s2.row_state).toBe(s1.row_state);
    expect(S(stored(g.id)!)).toBe(String(s1.row_state));
  });

  it("[CONTROL] the stamp carries both fields: fingerprint byte-identical to the escalation's, row_state = S", async () => {
    // fingerprint is what the supply's current predicate parses, so it is kept exactly as before; row_state is new.
    const ni = seed({ id: `inv-refused-both-ni-${RUN}`, summary: "a capability count is zero", classification_metadata: { falsifier: "none", failure_lessons: [{ class: "verify_failed", reason: "r", at: "2030-01-01T00:00:00.000Z" }] } });
    await decompose(ni.id);
    const a = metaOf(ni.id).investigation_declined as Row;
    expect(Object.keys(a).sort()).toEqual(["at", "fingerprint", "reason", "row_state"]);
    expect(a.fingerprint).toBe(g2f.chronicEscalationFingerprint(ni, "investigation_declined"));
    expect(a.row_state).toBe(S(ni));
    expect(String(a.row_state)).toMatch(/^[0-9a-f]{64}$/);
    const g = sitedRow("both");
    replies.push({ steps: [missingStep("missing-a.ts")] });
    await decompose(g.id);
    const b = metaOf(g.id).investigation_declined as Row;
    expect(b.fingerprint).toBe(g2f.chronicEscalationFingerprint(g, "investigation_declined"));
    expect(b.row_state).toBe(S(g));
  });

  it("[CONTROL] a decomposition that wrote a step (and refused another) is not stamped", async () => {
    const g = sitedRow("wrote");
    replies.push({ steps: [validStep, missingStep("missing-a.ts")] });
    const r = await decompose(g.id);
    expect((r.body as Row).children).toEqual([`${g.id}-step-1`]);
    expect(metaOf(g.id).investigation_declined).toBeUndefined();
  });

  it("[CONTROL] a needs_information decline is stamped with S; observe mode writes nothing", async () => {
    const g = seed({ id: `inv-refused-ni-${RUN}`, summary: "a capability count is zero", classification_metadata: { falsifier: "none" } });
    const r = await decompose(g.id);
    expect(String((r.body as Row).reason)).toStartWith("needs_information");
    expect((metaOf(g.id).investigation_declined as Row).row_state).toBe(S(g));
    const o = sitedRow("observe");
    replies.push({ steps: [missingStep("missing-a.ts")] });
    await decompose(o.id, { learning_mode: "observe" });
    expect(writesFor(o.id)).toEqual([]);
  });

  it("[CONTROL] a row's own stamp, and the investigation route's and the escalation's fields, leave its S unchanged", () => {
    const row = { id: "s-own-stamp", status: "open", summary: "x", classification_metadata: { falsifier: "none", edit_site: SITE } };
    const s = S(row);
    const after = { ...row, classification_metadata: { ...row.classification_metadata, investigation_declined: { fingerprint: "{}", row_state: s, at: "t", reason: "no valid step: a" }, investigated_at: "t", chronic_escalation_at: "t" } };
    expect(S(after)).toBe(s);
  });
});

