describe("S reproduces every shared vector byte for byte", () => {
  const byName = new Map(VECTORS.map((v) => [v.name, v]));
  it("[CONTROL] the vector set is present (27 vectors)", () => { expect(VECTORS.length).toBe(27); });
  for (const v of VECTORS) {
    it(`[PARITY] ${v.name}`, () => {
      expect(g2f.rowStateCanonical(v.row)).toBe(v.canonical);
      expect(S(v.row)).toBe(v.s);
      if (v.same_as) expect(S(v.row)).toBe(byName.get(v.same_as)!.s);
      if (v.differs_from) expect(S(v.row)).not.toBe(byName.get(v.differs_from)!.s);
    });
  }
  it("[PARITY] fixtures (a) to (f): refusal-only SAME, parent check DIFFERENT, other lesson class DIFFERENT (by design), *_at only SAME, re-emission counts only SAME", () => {
    const s = (n: string) => S(byName.get(n)!.row);
    expect(s("a_refusal_only_change")).toBe(s("base"));
    expect(s("b_parent_check")).not.toBe(s("base"));
    expect(s("c_other_lesson_class")).not.toBe(s("base"));
    expect(s("d_only_at_keys_changed")).toBe(s("base"));
    const f = byName.get("f_reemission_counts_only")!;
    expect(f.same_as).toBeDefined();
    expect(s("f_reemission_counts_only")).toBe(s(f.same_as!));
  });
});
